<script>document.querySelectorAll('[name="assignment_type"]').forEach(radio=>radio.addEventListener('change',()=>{document.getElementById('initiate-person-label').innerHTML=(radio.value==='owner'?'Project Owner':'Project Manager')+' <b>*</b>';}));const selectedReviewer=document.querySelector('[name="assignment_type"]:checked');if(selectedReviewer)selectedReviewer.dispatchEvent(new Event('change'));</script>
<script>const sub=document.getElementById('flow-subsidiary');function preview(){document.getElementById('flow-code').textContent=sub.selectedOptions[0]?.dataset.preview||'Assigned automatically on save';}sub.addEventListener('change',preview);preview();</script>
<script>const planMode=document.getElementById('initiate-plan-mode');function optionalPlan(){const on=planMode.value!=='none',templated=planMode.value==='template';document.querySelectorAll('[data-starting-plan]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.startingPlan===planMode.value)));document.getElementById('clear-starting-plan').hidden=!on;document.getElementById('initiate-plan-fields').disabled=!on;document.getElementById('initiate-template-field').hidden=!templated;document.getElementById('browse-starting-template').hidden=!templated;document.getElementById('edit-blank-plan').hidden=templated;const select=document.getElementById('initiate-template-id');select.disabled=!templated;select.required=templated;document.querySelectorAll('#initiate-plan-fields input[type=date]').forEach(input=>input.required=on);}planMode.addEventListener('change',optionalPlan);document.querySelectorAll('[data-starting-plan]').forEach(button=>button.addEventListener('click',()=>{planMode.value=button.dataset.startingPlan;planMode.dispatchEvent(new Event('change',{bubbles:true}));}));document.getElementById('clear-starting-plan').addEventListener('click',()=>{planMode.value='none';planMode.dispatchEvent(new Event('change',{bubbles:true}));});optionalPlan();</script>
